1: /**
2:  * Runes controller for the operator loan queue board (ALE-359).
3:  *
4:  * Owns everything on the board that is not markup: the queue read, the
5:  * default-view / `?view=` rule, the action-sheet selection and its draft,
6:  * drop-target resolution and the drop decision, and the six loan commands
7:  * with their freshness and error policy. It holds no XState actor:
8:  * `decideLoanDrop` stays a pure decision it calls. Phoenix stays the only
9:  * authority on loan state — a drop never writes, it opens the action sheet,
10:  * whose command is the single write path.
11:  *
12:  * Drag-and-drop (`@thisux/sveltednd`), the media query, and DOM focus stay in
13:  * the page; the controller takes plain inputs so it is testable without them.
14:  */
15: import { goto } from "$app/navigation";
16: import { page } from "$app/state";
17: import {
18: 	createMutation,
19: 	createQuery,
20: 	useQueryClient,
21: 	type QueryClient,
22: } from "@tanstack/svelte-query";
23: import {
24: 	type InventoryOperatorLoan,
25: 	type InventoryOperatorLoanQueue,
26: 	type InventoryOperatorLoanQueueShowResponse,
27: 	type InventoryOperatorLoansApproveData,
28: 	type InventoryOperatorLoansApproveResponse,
29: 	type InventoryOperatorLoansCancelData,
30: 	type InventoryOperatorLoansCancelResponse,
31: 	type InventoryOperatorLoansCheckoutData,
32: 	type InventoryOperatorLoansCheckoutResponse,
33: 	type InventoryOperatorLoansEditDatesData,
34: 	type InventoryOperatorLoansEditDatesResponse,
35: 	type InventoryOperatorLoansRejectData,
36: 	type InventoryOperatorLoansRejectResponse,
37: 	type InventoryOperatorLoansReturnData,
38: 	type InventoryOperatorLoansReturnResponse,
39: 	type Options,
40: 	inventoryItemsListQueryKey,
41: 	inventoryItemsShowQueryKey,
42: 	inventoryOperatorLoanQueueShowOptions,
43: 	inventoryOperatorLoanQueueShowQueryKey,
44: 	inventoryOperatorLoansApproveMutation,
45: 	inventoryOperatorLoansCancelMutation,
46: 	inventoryOperatorLoansCheckoutMutation,
47: 	inventoryOperatorLoansEditDatesMutation,
48: 	inventoryOperatorLoansRejectMutation,
49: 	inventoryOperatorLoansReturnMutation,
50: } from "@dhc/api-client";
51: import { apiErrorMessage } from "#lib/api-error.js";
52: import {
53: 	decideLoanDrop,
54: 	type LoanQueueDropTarget,
55: } from "#lib/components/inventory/loan-queue-dnd.js";
56: 
57: export type QueueView = "requests" | "handovers" | "returns" | "maintenance";
58: 
59: export type LoanCardKind = "request" | "handover" | "return";
60: 
61: /** What a card carries as drag data. */
62: export type LoanDragData = {
63: 	loan: InventoryOperatorLoan;
64: 	readyForCheckout?: boolean;
65: };
66: 
67: /** The drag currently in progress, as the page's drag library reports it. */
68: export type LoanQueueHover = {
69: 	/** Droppable container id under the pointer: a column or `card:<loanId>`. */
70: 	targetContainer: string | null;
71: 	dragged: LoanDragData | undefined;
72: };
73: 
74: export type LoanQueueSelection = {
75: 	loan: InventoryOperatorLoan;
76: 	/** Advisory: only ever true when opened from a ready handover row. */
77: 	readyForCheckout: boolean;
78: 	/** Draft dates (`YYYY-MM-DD`) and note the commands are built from. */
79: 	startsOn: string;
80: 	dueOn: string;
81: 	note: string;
82: };
83: 
84: type Request<TData, TResponse> = (options: TData) => Promise<TResponse>;
85: 
86: /** Request functions; each defaults to the generated Phoenix client. */
87: export type LoanQueueBoardRequests = {
88: 	queue: () => Promise<InventoryOperatorLoanQueueShowResponse>;
89: 	approve: Request<
90: 		Options<InventoryOperatorLoansApproveData>,
91: 		InventoryOperatorLoansApproveResponse
92: 	>;
93: 	reject: Request<
94: 		Options<InventoryOperatorLoansRejectData>,
95: 		InventoryOperatorLoansRejectResponse
96: 	>;
97: 	cancel: Request<
98: 		Options<InventoryOperatorLoansCancelData>,
99: 		InventoryOperatorLoansCancelResponse
100: 	>;
101: 	checkout: Request<
102: 		Options<InventoryOperatorLoansCheckoutData>,
103: 		InventoryOperatorLoansCheckoutResponse
104: 	>;
105: 	returnLoan: Request<
106: 		Options<InventoryOperatorLoansReturnData>,
107: 		InventoryOperatorLoansReturnResponse
108: 	>;
109: 	editDates: Request<
110: 		Options<InventoryOperatorLoansEditDatesData>,
111: 		InventoryOperatorLoansEditDatesResponse
112: 	>;
113: };
114: 
115: export type LoanQueueBoardDeps = {
116: 	/** Defaults to the client from Svelte context. */
117: 	queryClient?: QueryClient;
118: 	requests?: Partial<LoanQueueBoardRequests>;
119: 	/** URL source for `?view=`; defaults to `page.url` from `$app/state`. */
120: 	url?: () => URL;
121: 	/** Pushes a history entry; defaults to `goto` from `$app/navigation`. */
122: 	navigate?: (url: URL) => void | Promise<void>;
123: 	/** The `lg` media-query result; drag only exists on the wide board. */
124: 	isDesktop?: () => boolean;
125: 	/** The drag in progress, if any. */
126: 	hover?: () => LoanQueueHover | undefined;
127: };
128: 
129: /**
130:  * The one mapping between board views and queue buckets, in board order.
131:  * `holdsLoans` is false for maintenance: its rows are items, not loans, so a
132:  * `card:<id>` drop target never resolves there.
133:  */
134: const VIEW_BUCKETS = [
135: 	{
136: 		view: "requests",
137: 		bucket: "pendingRequests",
138: 		label: "Requests",
139: 		holdsLoans: true,
140: 	},
141: 	{
142: 		view: "handovers",
143: 		bucket: "handoversDue",
144: 		label: "Ready for handover",
145: 		holdsLoans: true,
146: 	},
147: 	{
148: 		view: "returns",
149: 		bucket: "returnsAndOverdue",
150: 		label: "Returns and overdue",
151: 		holdsLoans: true,
152: 	},
153: 	{
154: 		view: "maintenance",
155: 		bucket: "openMaintenance",
156: 		label: "Open maintenance",
157: 		holdsLoans: false,
158: 	},
159: ] as const satisfies readonly {
160: 	view: QueueView;
161: 	bucket: keyof InventoryOperatorLoanQueue;
162: 	label: string;
163: 	holdsLoans: boolean;
164: }[];
165: 
166: /** Default view: the first non-empty bucket in this order, else requests. */
167: const DEFAULT_VIEW_PRIORITY = [
168: 	"requests",
169: 	"returns",
170: 	"handovers",
171: 	"maintenance",
172: ] as const satisfies readonly QueueView[];
173: 
174: export function parseQueueView(value: string | null): QueueView | undefined {
175: 	return VIEW_BUCKETS.find((entry) => entry.view === value)?.view;
176: }
177: 
178: function bucketFor(view: QueueView) {
179: 	// SAFETY: VIEW_BUCKETS lists every QueueView, so the lookup always hits.
180: 	return VIEW_BUCKETS.find((entry) => entry.view === view)!.bucket;
181: }
182: 
183: function trimmedNote(note: string): string | undefined {
184: 	return note.trim() || undefined;
185: }
186: 
187: export function createLoanQueueBoard(deps: LoanQueueBoardDeps = {}) {
188: 	const queryClient = deps.queryClient ?? useQueryClient();
189: 	const client = () => queryClient;
190: 	const requests = deps.requests ?? {};
191: 	const url = deps.url ?? (() => page.url);
192: 	const navigate =
193: 		deps.navigate ?? ((next: URL) => goto(next, { reset: false }));
194: 	const isDesktop = deps.isDesktop ?? (() => false);
195: 	const hover = deps.hover ?? (() => undefined);
196: 
197: 	let selection = $state<LoanQueueSelection | undefined>();
198: 	let error = $state<string | null>(null);
199: 	let notice = $state<string | null>(null);
200: 
201: 	const queue = createQuery(
202: 		() => ({
203: 			...inventoryOperatorLoanQueueShowOptions(),
204: 			...(requests.queue && { queryFn: requests.queue }),
205: 			select: (response: InventoryOperatorLoanQueueShowResponse) =>
206: 				response.data,
207: 		}),
208: 		client,
209: 	);
210: 
211: 	const buckets = $derived(queue.data);
212: 
213: 	const views = $derived(
214: 		VIEW_BUCKETS.map(({ view, bucket, label }) => ({
215: 			value: view,
216: 			label,
217: 			count: buckets?.[bucket].count ?? 0,
218: 		})),
219: 	);
220: 
221: 	const defaultView = $derived<QueueView>(
222: 		DEFAULT_VIEW_PRIORITY.find((view) => buckets?.[bucketFor(view)].count) ??
223: 			"requests",
224: 	);
225: 	const activeView = $derived(
226: 		parseQueueView(url().searchParams.get("view")) ?? defaultView,
227: 	);
228: 
229: 	function changeView(value: string) {
230: 		const view = parseQueueView(value);
231: 		if (!view || view === activeView) return;
232: 		const next = new URL(url().href);
233: 		next.searchParams.set("view", view);
234: 		void navigate(next);
235: 	}
236: 
