162: 	if (targetContainer.startsWith("nest:")) {
163: 		return targetContainer.slice("nest:".length);
164: 	}
165: 	return undefined;
166: }
167: 
168: function containerSnapshots(): ContainerSnapshot[] {
169: 	return containers.map((container) => ({
170: 		id: container.id,
171: 		parentContainerId: container.parentContainerId,
172: 		archivedAt: container.archivedAt,
173: 	}));
174: }
175: 
176: /**
177:  * Whether the zone for `targetId` (null is the Root zone) is currently
178:  * hovered with a container the machine would refuse. Drives the red
179:  * `drag-invalid` outline so a disallowed hover reads before the drop.
180:  */
181: function invalidHover(targetId: string | null): boolean {
182: 	if (!dndState.isDragging) return false;
183: 	if (
184: 		dndState.targetContainer !==
185: 		(targetId === null ? "root" : `nest:${targetId}`)
186: 	) {
187: 		return false;
188: 	}
189: 	// SAFETY: every draggable on this page sets dragData to ContainerDragData;
190: 	// anything else means no drag started here and there is nothing to judge.
191: 	const dragged = dndState.draggedItem as ContainerDragData | undefined;
192: 	if (!dragged?.container.id) return false;
193: 	return (
194: 		decideContainerDrop({
195: 			draggedId: dragged.container.id,
196: 			targetId,
197: 			containers: containerSnapshots(),
198: 		}).kind !== "move"
199: 	);
200: }
201: 
202: function handleContainerDrop(state: DragDropState<ContainerDragData>) {
203: 	const dragged = state.draggedItem;
204: 	if (!dragged || !state.targetContainer) return;
205: 	const targetId = resolveDropTarget(state.targetContainer);
206: 	if (targetId === undefined) return;
207: 	const outcome = decideContainerDrop({
208: 		draggedId: dragged.container.id,
209: 		targetId,
210: 		containers: containerSnapshots(),
211: 	});
212: 	if (outcome.kind === "move") {
213: 		dndNotice = null;
214: 		moveContainer.mutate({
215: 			path: { id: dragged.container.id },
216: 			body: { parentContainerId: outcome.parentId },
217: 		});
218: 	} else if (outcome.kind === "ignored") {
219: 		dndNotice = null;
220: 	} else {
221: 		dndNotice = outcome.reason;
222: 	}
223: }
224: function handleSave(result: typeof saveContainer.result) {
225: 	if (!result) return;
226: 	// Errors render inline in the form via `remoteForm.result`; no toast so
227: 	// the message never covers the submit button.
228: 	if (!result.ok) return;
229: 	// Success shows a green check in the submit button, then the editor
230: 	// closes — no success toast, so nothing lingers over the next action.
231: 	saveSucceeded = true;
232: 	refresh();
233: 	clearTimeout(saveTimer);
234: 	saveTimer = setTimeout(() => {
235: 		editorOpen = false;
236: 		reset();
237: 	}, 650);
238: }
239: function startEdit(container: InventoryContainer) {
240: 	editing = container;
241: 	saveSucceeded = false;
242: 	draft = {
243: 		name: container.name,
244: 		description: container.description ?? "",
245: 		parentId: container.parentContainerId ?? "",
246: 	};
