202: async function addCategory(trigger: HTMLElement) {
203: 	categoryEditorTrigger = trigger;
204: 	editingCategory = undefined;
205: 	categoryName = "";
206: 	categoryDescription = "";
207: 	categoryEditorOpen = true;
208: 	await tick();
209: 	categoryNameInput?.focus();
210: }
211: function cancelCategoryEdit() {
212: 	editingCategory = undefined;
213: 	categoryName = "";
214: 	categoryDescription = "";
215: 	categoryEditorOpen = false;
216: 	categorySucceeded = false;
217: 	clearTimeout(categoryTimer);
218: }
219: function optionDraft(option: { id: string; label: string; position: number }) {
220: 	return (
221: 		optionDrafts[option.id] ?? {
222: 			label: option.label,
223: 			position: option.position,
224: 		}
225: 	);
226: }
227: 
228: function setOptionDraft(
229: 	option: { id: string; label: string; position: number },
230: 	field: "label" | "position",
231: 	value: string,
232: ) {
233: 	const current = optionDraft(option);
234: 	optionDrafts[option.id] = {
235: 		...current,
236: 		[field]: field === "position" ? Number(value) : value,
237: 	};
238: }
239: function editOption(option: { id: string; label: string; position: number }) {
240: 	optionDrafts[option.id] = { label: option.label, position: option.position };
241: 	editingOptionId = option.id;
242: }
243: function cancelOptionEdit(optionId: string) {
244: 	delete optionDrafts[optionId];
245: 	editingOptionId = undefined;
246: }
247: function handleCategorySave(result: typeof saveCategory.result) {
248: 	if (!result) return;
249: 	// Errors render inline in the sheet; success flashes the submit button
250: 	// green and then closes — no toast to linger over the list.
251: 	if (!result.ok) return;
252: 	categorySucceeded = true;
253: 	refreshAll();
254: 	clearTimeout(categoryTimer);
255: 	categoryTimer = setTimeout(() => cancelCategoryEdit(), 650);
256: }
257: function handleDefinitionSave(result: typeof saveDefinition.result) {
258: 	if (!result) return;
259: 	if (!result.ok) return;
260: 	definitionSucceeded = true;
261: 	refreshAll();
262: 	clearTimeout(definitionTimer);
263: 	definitionTimer = setTimeout(() => resetDefinition(), 650);
264: }
265: function handleOptionCreate(result: typeof createOption.result) {
266: 	if (!result) return false;
267: 	if (!result.ok) return false;
268: 	refreshAll();
